    public RemoteFunctionCall<Tuple2<Boolean, Boolean>> verifyHistoricalStatus(String _key,
            BigInteger _bankId, BigInteger _timestamp) {
        final Function function = new Function(FUNC_VERIFYHISTORICALSTATUS, 
                Arrays.<Type>asList(new org.web3j.abi.datatypes.Address(160, _key), 
                new org.web3j.abi.datatypes.generated.Uint256(_bankId), 
                new org.web3j.abi.datatypes.generated.Uint256(_timestamp)), 
                Arrays.<TypeReference<?>>asList(new TypeReference<Bool>() {}, new TypeReference<Bool>() {}));
        return new RemoteFunctionCall<Tuple2<Boolean, Boolean>>(function,
                new Callable<Tuple2<Boolean, Boolean>>() {
                    @Override
                    public Tuple2<Boolean, Boolean> call() throws Exception {
                        List<Type> results = executeCallMultipleValueReturn(function);
                        return new Tuple2<Boolean, Boolean>(
                                (Boolean) results.get(0).getValue(), 
                                (Boolean) results.get(1).getValue());
                    }
                });
    }

